<?php session_start();require 'config.php';$q=trim($_GET['q']??'');if($q){$s=$conn->prepare('SELECT * FROM courses WHERE title LIKE ? OR description LIKE ? ORDER BY id');$x='%'.$q.'%';$s->bind_param('ss',$x,$x);}else{$s=$conn->prepare('SELECT * FROM courses ORDER BY id');}$s->execute();$courses=$s->get_result();?><!doctype html><html lang='fa' dir='rtl'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>دوره‌ها | Erfan Academy</title><link rel='stylesheet' href='style.css'></head><body><header><a class='brand' href='index.php'>🎓 آکادمی عرفان</a><nav><a href='index.php'>خانه</a><a href='courses.php'>دوره‌ها</a><a href='about.php'>درباره ما</a><a href='contact.php'>تماس</a></nav></header><main><h1>📚 دوره‌های آموزشی</h1><form><input name='q' placeholder='جستجوی دوره...' value='<?=htmlspecialchars($q)?>'><button class='btn'>جستجو</button></form><div class='grid'><?php while($c=$courses->fetch_assoc()): ?><article class='course'><div class='icon'>📘</div><h2><?=htmlspecialchars($c['title'])?></h2><p><?=htmlspecialchars($c['description'])?></p><div class='price'><?=number_format($c['price'])?> تومان</div><br><a class='btn' href='lesson.php?id=<?=$c['id']?>'>مشاهده دوره</a></article><?php endwhile; ?></div></main><footer>© 2026 Erfan Academy</footer></body></html>